import React, { Component } from 'react'
import { connect } from 'react-redux'
import {
  Button, Select, Row, Col, Form,
  Alert, Modal, Divider
} from 'antd'
import authAction from '../../../redux/auth/actions'
import SignInStyleWrapper from './index.style'
import NumericInput from '../../../components/NumericInput'
import validator from '../../../helpers/validator'
import getDocumentReferrer from '../../../helpers/getDocumentReferrer'
import isTrustedDomain from '../../../helpers/isTrustedDomain'
import Phone from '../../../image/phone.png'
import Otp from '../../../image/otp.png'
import IntlMessages from '../../../components/utility/intlMessages'
import GoLifeLoginNew from '../../../image/go-life-cover.png'
import BgLoginNew from '../../../image/bg-new.png'
import BgLogin from '../../../image/gopassenger.png'
import BgLogin1 from '../../../image/golifemobile.jpg'

import $ from 'jquery'
import { COUNTRY_CODES, RESEND_OTP_COUNT_DOWN } from '../../../constants/constants'
import { millisecondToHMS } from '../../../helpers/utility'
import { ERROR_STRINGS } from '../../../constants/lang'

const FormItem = Form.Item
const Option = Select.Option

const { login, generateOtp, resetStatus,
  authVerifyOtp, resendOtpRequest, clearVerifyOtpError
} = authAction

class SignIn extends Component {
  constructor (props) {
    super(props)
    this.state = {
      loading: false,
      errorMessage: '',
      visible: false,
      isFrom: '/',
      operationId: window.sessionStorage.getItem('operationId') || '',
      stopwatch: RESEND_OTP_COUNT_DOWN,
      countryCode: '62'
    }
    this.mobileNumber = null
    this.decrementer = null
    this.resendCount = parseInt(window.sessionStorage.getItem('count'), 10) || 0
  }

  componentDidMount () {
    $('.mobile-number-input').on('focus', function () {
      document.body.scrollTop = $(this).offset().top
    })
  }
  componentWillReceiveProps (nextProps) {
    const locationState = this.props.history.location.state || {}
    const from = locationState.from || {}
    const fromPathname = from.pathname || from
    if (nextProps.errorMessage !== undefined) {
      this.setState({ errorMessage: nextProps.errorMessage, loading: false })
    }
    if (fromPathname) {
      this.setState({ isFrom: fromPathname })
    }
  }
  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }
  handleFormSubmit = async (e) => {
    if (this.props.operationId) {
      await this.handleVerifyOtp(e)
    } else {
      await this.handleOtpRequest(e)
    }
  }
  handleOtpRequest = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    this.setState({ loading: true })
    const { form } = this.props
    const payload = form.getFieldsValue()
    this.mobileNumber = payload.mobile_number
    this.props.resetStatus()
    setTimeout(() => {
      this.props.generateOtp({
        phone: `${this.state.countryCode}-${this.mobileNumber}`
      })
      this.startTimer()
    }, 1000)
  }
  handleVerifyOtp = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const { form, operationId } = this.props
    const payload = form.getFieldsValue()
    const data = {
      operation_id: operationId,
      otp: payload.otp
    }
    this.props.authVerifyOtp({ body: data })
  }
  resendOtp = () => {
    if (this.resendCount < 5) {
      // if count is less than 5 then call send otp with operation id
      this.resendCount = this.resendCount + 1
      window.sessionStorage.setItem('count', this.resendCount)
      const { operationId } = this.state
      this.props.resendOtpRequest({
        operationId,
        mobileNumber: `${this.state.countryCode}-${this.mobileNumber}`
      })
    } else {
      // it count is greater than or equal to 6 then call this with mobile number
      this.resendCount = 0
      window.sessionStorage.setItem('count', 300)
      const { phone } = this.state
      this.props.generateOtp({ phone })
    }
    this.setState({
      stopwatch: RESEND_OTP_COUNT_DOWN
    },
    () => {
      if (this.props.verifyOtpError) {
        this.props.clearVerifyOtpError()
      }
      this.startTimer()
    })
  }
  startTimer () {
    // If interval exists we clear it
    if (this.decrementer) {
      clearInterval(this.decrementer)
    }
    // Then we decrement stopwatch by 1 every second
    this.decrementer = setInterval(() => {
      let countDown = this.state.stopwatch - 1000
      window.sessionStorage.setItem('policiesCountDown', countDown)
      this.setState({ stopwatch: countDown })
    }, 1000)
  }
  onChange = value => {
    if (this.props.verifyOtpError) {
      this.props.clearVerifyOtpError()
    }
    this.setState({ value })
  }
  showModal = () => {
    this.setState({ visible: true })
  }
  handleCancel = e => {
    this.setState({ visible: false })
  }
  onCountryCodeSelect = e => {
    this.setState({ countryCode: e })
  }
  msToHMS = ms => {
    return millisecondToHMS(ms)
  }
  getPartenerLoginSubTitle = () => {
    const isGojek = window.sessionStorage.getItem('isFromGojek')
    const isGolife = window.sessionStorage.getItem('isFromGolife')
    const partner = isGojek === 'true' ? 'GO_JEK' : isGolife === 'true' ? 'GO_LIFE' : ''
    switch (partner) {
      case 'GO_JEK':
        return 'No telepon terdaftar di aplikasi GO-JEK'
      case 'GO_LIFE':
        return 'Masukkan no telepon terdaftar di aplikasi GO-LIFE'
      default:
        return 'Masukkan nomor telepon terdaftar Anda untuk mengajukan klaim'
    }
  }
  needHelpModal = (isGojek) => {
    const title = `Nomor telepon yang diisi adalah nomor Anda yang telah terdaftar di ${isGojek === 'true' ? 'GO-JEK' : 'GO-LIFE'}.`
    return <Modal
      title=''
      visible={this.state.visible}
      footer={[
        <Button key='ok' onClick={this.handleCancel}>
          <IntlMessages id='Ok' />
        </Button>
      ]}
      closable={false}
    >
      <p>
        <b>
          <IntlMessages id={title}
          />
        </b>
      </p>
      <p>
        <b>
          <IntlMessages id='Jika butuh bantuan lebih lanjut, hubungi CS kami:' />
        </b>
      </p>
      {/* <p>
        <b>Telepon: 021 5089 0580</b>
      </p> */}
      <p>
        <b>Whatsapp: (+62) 818 343 494</b>
      </p>
    </Modal>
  }
  countryCodeOptions (isDisabled) {
    return (
      <Select defaultValue='+62' onSelect={this.onCountryCodeSelect} disabled={isDisabled}>
        {
          COUNTRY_CODES.map(country =>
            <Option value={country.value}>{country.displayName}</Option>
          )
        }
      </Select>
    )
  }
  getMobileNumberField = (isDisabled) => {
    const { getFieldDecorator } = this.props.form
    return (<FormItem style={{ width: '100%' }}>
      {getFieldDecorator('mobile_number', {
        rules: [
          {
            required: true,
            message: <IntlMessages id='Nomor handphone tidak boleh kosong' />
          },
          { validator: validator.checkPhone }
        ],
        initialValue: this.mobileNumber
      })(
        <NumericInput
          className='mobile-number-input'
          addonBefore={this.countryCodeOptions(isDisabled)}
          onChange={this.onChange}
          disabled={isDisabled}
          minLength={9}
          maxLength={12}
        />
      )}
    </FormItem>)
  }
  getOTPField = () => {
    const { getFieldDecorator } = this.props.form
    return <FormItem style={{ width: '100%' }}>
      {getFieldDecorator('otp', {
        rules: [
          {
            required: true,
            message: (
              <IntlMessages id='OTP tidak boleh kosong' />
            )
          },
          { validator: validator.checkOtp }
        ]
      })(
        <NumericInput
          className='otp-input'
          autoFocus
          type='otp'
          onChange={this.onChange}
          disabled={false}
          minLength='6'
          maxLength='6'
          autocomplete='off'
        />
      )}
    </FormItem>
  }
  getSendOTPRequestBtn = () => {
    const { generateAuthOtpLoading } = this.props
    return <div className='btn-otp-container'>
      <Button
        type='primary'
        className='button btn-otp'
        htmlType='submit'
        loading={!!generateAuthOtpLoading}
        disabled={this.state.value === undefined || this.state.value === ''}
      >
        <IntlMessages id='Kirim OTP' />
      </Button>
    </div>
  }
  getResendAndSubmitBtn = () => {
    const { verifyAuthOtpLoading } = this.props
    return <div className='btn-otp-container'>
      <Button
        type='primary'
        className='button btn-otp '
        disabled={this.state.stopwatch > 0}
        style={{
          margin: '0 10px 0 0',
          height: '50px'
        }}
        onClick={this.resendOtp}
      >
        <IntlMessages id='Kirim ulang OTP' /> &nbsp;&nbsp;
        {this.state.stopwatch > 0 &&
          this.msToHMS(this.state.stopwatch)}
      </Button>
      <Button
        type='primary'
        className='button btn-otp'
        htmlType='submit'
        loading={!!verifyAuthOtpLoading}
        disabled={
          this.state.value === undefined ||
          this.state.value === ''
        }
        style={{
          margin: '0 0 0 10px',
          height: '50px'
        }}
      >
        <IntlMessages id='Submit' />
      </Button>
    </div>
  }
  redirectionHandler = (from) => {
    const urlObj = getDocumentReferrer()
    if (urlObj.pathname && urlObj.pathname.includes('/endorsement') && isTrustedDomain(urlObj.host)) {
      window.location.href = urlObj.href
    } else {
      from === '/'
        ? window.location.reload()
        : window.history.pushState({}, null, from)
    }
  }
  render () {
    const { history } = this.props
    const { isFrom, visible } = this.state
    const { operationId, verifyOtpError } = this.props
    window.onpopstate = e => {
      history.push('/')
    }
    if (this.props.isLoggedIn) {
      this.redirectionHandler(isFrom)
    }
    let isGojek = window.sessionStorage.getItem('isFromGojek')
    return (
      <SignInStyleWrapper bg={isGojek === 'true' ? BgLoginNew : GoLifeLoginNew}>
        <div className='container'>
          {!!visible && this.needHelpModal()}
          <div className='hero' style={{ backgroundImage: (isGojek === 'true' ? `url(${BgLogin})` : `url(${BgLogin1})`) }} />
          <Row type='flex' className='content-row' style={{
            justifyContent: isGojek === 'true' ? 'center' : 'baseline',
            marginLeft: isGojek === 'true' ? '' : 350
          }}>
            <Col xs={23} sm={12} md={8} className='container-col'>
              <div className={`${isGojek === 'true' ? 'hero-title' : 'hero-title-golife'}`}>
                <div className='title-text'>
                  <IntlMessages id='Kami turut bersimpati atas musibah' />{' '}
                  <br />
                  <IntlMessages id='yang Anda alami.' />
                </div>
              </div>
              <center><hr /></center>
              <div className='otp-box'>
                <div className='sub-title'>
                  <IntlMessages id={this.getPartenerLoginSubTitle()} />
                </div>
                <div className='otp-info'>
                  <IntlMessages id='Dapatkan SMS berisi kode OTP lalu Sign In untuk klaim asuransi Anda' />
                </div>
                {/* <div className="card"> */}
                <Form onSubmit={this.handleFormSubmit} id='myForm'>
                  <Row type='flex'>
                    <Col xs={24} sm={24}>
                      <div className='input-phone'>
                        <div className='phone-logo'>
                          <img src={Phone} alt='Phone Number' />
                        </div>
                        {this.getMobileNumberField(!!operationId)}
                        <Divider />
                      </div>
                    </Col>
                    {
                      !!operationId && <Col xs={24} sm={24}>
                        <div className='input-phone'>
                          <div className='phone-logo'>
                            <img src={Otp} alt='OTP' />
                          </div>
                          {this.getOTPField()}
                          <Divider />
                        </div>
                      </Col>
                    }
                    <Col xs={24} sm={24}>
                      {operationId ? this.getResendAndSubmitBtn() : this.getSendOTPRequestBtn()}
                    </Col>
                    <Col xs={24} sm={24} className='mobile-help'>
                      <div className='help'>
                        <p onClick={this.showModal}><IntlMessages id='Butuh bantuan' /></p>
                      </div>
                    </Col>
                    <Col xs={24} sm={24} className='desktop-help'>
                      <div className='help'>
                        <p onClick={this.showModal}>
                          <IntlMessages id='Butuh bantuan' />
                        </p>
                      </div>
                    </Col>
                  </Row>
                </Form>
                {
                  (this.state.errorMessage !== '' || verifyOtpError) && (
                    <Col>
                      <Alert
                        message={this.state.errorMessage}
                        description={
                          <IntlMessages id={verifyOtpError || ERROR_STRINGS.serverError} />
                        }
                        type='error'
                        showIcon='showIcon'
                      />
                    </Col>)
                }
              </div>
              {/* </div> */}
            </Col>
          </Row>
        </div>
      </SignInStyleWrapper>
    )
  }
}
const WrappedDSigninCardForm = Form.create()(SignIn)
export default connect(state => ({
  isLoggedIn: state.Auth.idToken !== null,
  operationId: state.Auth.operationId,
  phone: state.Auth.phone,
  verifyOtpError: state.Auth.verifyOtpError,
  verifyAuthOtpLoading: state.Loading.AUTH_VERIFY_OTP,
  generateAuthOtpLoading: state.Loading.GENERATE_OTP,
  generateAuthOtpError: state.Error.GENERATE_OTP,
  errorMessage: state.Auth.errorMessage
}), {
  login,
  generateOtp,
  resendOtpRequest,
  clearVerifyOtpError,
  authVerifyOtp,
  resetStatus
})(WrappedDSigninCardForm)
